import express from 'express';
import { z } from 'zod';

const produk = [
  { id: 1, nama: 'Kopi Susu', kategori: 'minuman', harga: 18000 },
  { id: 2, nama: 'Teh Tarik', kategori: 'minuman', harga: 12000 },
  { id: 3, nama: 'Roti Bakar', kategori: 'makanan', harga: 15000 },
  { id: 4, nama: 'Es Kopi', kategori: 'minuman', harga: 15000 },
  { id: 5, nama: 'Kopi Hitam', kategori: 'minuman', harga: 10000 },
];
const Query = z.object({
  q: z.string().default(''),
  kategori: z.string().optional(),
  urut: z.enum(['harga', '-harga', 'nama']).default('nama'),
  halaman: z.coerce.number().int().min(1).default(1),
  per: z.coerce.number().int().min(1).max(50).default(2),
});
const app = express();
app.get('/produk', (req, res) => {
  const h = Query.safeParse(req.query);
  if (!h.success) return res.status(400).json({ error: 'Query tidak valid' });
  const { q, kategori, urut, halaman, per } = h.data;
  let hasil = produk.filter((p) => p.nama.toLowerCase().includes(q.toLowerCase()) && (!kategori || p.kategori === kategori));
  const kolom = urut.replace('-', '');
  const arah = urut.startsWith('-') ? -1 : 1;
  hasil = hasil.toSorted((a, b) => (a[kolom] > b[kolom] ? 1 : a[kolom] < b[kolom] ? -1 : 0) * arah);
  const mulai = (halaman - 1) * per;
  res.json({ data: hasil.slice(mulai, mulai + per).map((p) => p.nama), meta: { total: hasil.length, halaman, per, jumlahHalaman: Math.ceil(hasil.length / per) } });
});
const server = app.listen(3000);

for (const query of ['?q=kopi&urut=harga', '?q=kopi&urut=harga&halaman=2', '?kategori=minuman&urut=-harga&per=3', '?per=500']) {
  const r = await fetch('http://localhost:3000/produk' + query);
  const d = await r.json();
  console.log(r.status, d.data ?? d.error, d.meta?.total);
}
server.close();

