import express from 'express';
const produk = ['Kopi', 'Teh', 'Roti', 'Jus', 'Susu'].map((nama, i) => ({ id: i + 1, nama }));
const app = express();
app.get('/produk', (req, res) => {
  const halaman = Number(req.query.halaman ?? 1);
  const per = Number(req.query.per ?? 2);
  const mulai = (halaman - 1) * per;
  res.json({ data: produk.slice(mulai, mulai + per).map((p) => p.nama), total: produk.length });
});
const server = app.listen(3000);
console.log(await (await fetch('http://localhost:3000/produk?halaman=2')).json());
server.close();

