const data = [1, 2, 3, 4, 5, 6, 7];
function halaman(data, nomor, per) {
  const mulai = (nomor - 1) * per;
  return { isi: data.slice(mulai, mulai + per), jumlahHalaman: Math.ceil(data.length / per) };
}
